put name="cohort" value="<?= e($account['cohort']??'') ?>"></label><label>Telepon<input name="phone" value="<?= e($account['phone']??'') ?>"></label><label>Kata sandi baru (opsional)<input type="password" name="password" minlength="8"></label><button class="btn btn-primary">Simpan perubahan</button></form><form method="post" data-confirm="<?= $account['is_active']?'Nonaktifkan':'Aktifkan' ?> akun ini?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="user_id" value="<?= (int)$account['id'] ?>"><button class="btn btn-light"><?= $account['is_active']?'Nonaktifkan':'Aktifkan' ?></button></form><form method="post" data-confirm="Hapus akun tanpa riwayat transaksi?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete_user"><input type="hidden" name="user_id" value="<?= (int)$account['id'] ?>"><button class="btn btn-danger-light">Hapus akun</button></form></div></details></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
